/**
 * «الانعكاس» — the reflex: the answers the mind must give **instantly**, with no engine, no library search and no
 * waiting — the questions a visitor actually asks most (shipping to my country, my customs, can you carry perfume).
 *
 * The table is generated by «المعلم»'s sibling robot from the site's real files (`scripts/shaheen-mind/reflex.ts` →
 * `src/data/live/shaheen-reflex.json`): every entry carries the number, its source and its date. Nothing is
 * calculated at answer time, so the reflex can never drift from the price engine — it is rebuilt from it.
 *
 * Pure and browser-safe: the same answer on the server and in the visitor's browser.
 */
import reflexData from '../data/live/shaheen-reflex.json';

export interface ReflexEntry {
  id: string;
  /** The kind of question this answers — used to match intent, not just a country name. */
  kind: 'shipping' | 'customs' | 'perfume_on_board';
  /** The destination's or carrier's name in Arabic, as it appears in the site's files. */
  nameAr: string;
  /** Country code / carrier id, as an extra anchor for the match. */
  code: string;
  lang: 'ar' | 'en';
  question: string;
  answerAr: string;
  answerEn: string;
  source: string;
  checkedAt: string;
  specialistId: string;
}

export interface ReflexFile { version: 1; updatedAt: string; entries: ReflexEntry[] }

export const REFLEX = reflexData as ReflexFile;

const SHIPPING_INTENT = /(شحن|توصيل|shipping|delivery)/i;
const CUSTOMS_INTENT = /(جمارك|ضريبه|رسوم|vat|customs|duty|tax)/i;
const PERFUME_INTENT = /(عطر|عطور|perfume|fragrance|un1266|مواد خطره|ماده خطره)/i;
/**
 * بوّابة الشات: الإجابة الفورية بتشتغل على سؤال لوجستي صريح بس (شحن/توصيل/جمارك/ضريبة/مادة خطرة).
 * «بكام العطر ده؟» سؤال سعر متجر — مش سؤال شحن، ومكانه محرك السعر، مش الانعكاس.
 */
const LOGISTICS_INTENT = /(شحن|توصيل|جمارك|ضريبه|رسوم|shipping|delivery|customs|duty|vat|un1266|مواد خطره|ماده خطره|dangerous|iata)/i;

const normalise = (text: string) => String(text || '').toLowerCase()
  .replace(/[\u064B-\u0652\u0670]/g, '')
  .replace(/[أإآ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه')
  .replace(/[٠-٩]/g, (d) => String(d.charCodeAt(0) - 0x0660))
  .replace(/\s+/g, ' ')
  .trim();

/** The entry this text is asking for — or `undefined` when it is not one of the reflex questions. */
export function matchReflex(text: string): ReflexEntry | undefined {
  const q = normalise(text);
  if (q.length < 6 || q.length > 240) return undefined;
  const asksShipping = SHIPPING_INTENT.test(q);
  const asksCustoms = CUSTOMS_INTENT.test(q);
  const asksPerfume = PERFUME_INTENT.test(q);
  if (!LOGISTICS_INTENT.test(q)) return undefined;
  if (!asksShipping && !asksCustoms && !asksPerfume) return undefined;
  // الأولوية لسؤال الجمارك لما السؤال جمارك فعلاً: «جمارك السعودية» مش سؤال عن سعر الشحن.
  const wanted: ReflexEntry['kind'][] = asksCustoms ? ['customs', 'shipping', 'perfume_on_board']
    : asksPerfume && !asksShipping ? ['perfume_on_board']
      : ['shipping', 'customs', 'perfume_on_board'];
  const ordered = wanted.flatMap((kind) => REFLEX.entries.filter((e) => e.kind === kind));

  // The entity must be named: a country or a carrier from the table.
  for (const entry of ordered) {
    // «بتشحنوا العطر؟» مالهاش بلد — قاعدة عامة واحدة للعطر (UN1266).
    if (entry.kind === 'perfume_on_board' && asksPerfume) return entry;
    const name = normalise(entry.nameAr);
    if (!name || name.length < 2) continue;
    const named = q.includes(name) || (entry.code.length >= 2 && new RegExp(`(^|[^a-z])${entry.code.toLowerCase()}([^a-z]|$)`).test(q));
    if (!named) continue;
    if (entry.kind === 'customs' && !asksCustoms) continue;
    if (entry.kind === 'shipping' && !asksShipping) continue;
    if (entry.kind === 'perfume_on_board' && !(asksPerfume || asksShipping)) continue;
    return entry;
  }
  return undefined;
}

/** The instant reply, or `undefined` when this is not a reflex question (then the normal path answers it). */
export function reflexAnswer(text: string, lang: 'ar' | 'en' = 'ar'): string | undefined {
  const entry = matchReflex(text);
  if (!entry) return undefined;
  return lang === 'en' ? entry.answerEn : entry.answerAr;
}

export const isReflexFile = (value: unknown): value is ReflexFile => {
  const f = value as ReflexFile | undefined;
  return Boolean(f && f.version === 1 && typeof f.updatedAt === 'string' && Array.isArray(f.entries)
    && f.entries.every((e) => e.answerAr && e.source && e.checkedAt));
};
